class Solution:
    def maxRotateFunction(self, nums: List[int]) -> int:
        f = sum(i * v for i, v in enumerate(nums))
        n, s = len(nums), sum(nums)
        ans = f
        for i in range(1, n):
            f = f + s - n * nums[n - i]
            ans = max(ans, f)
        return ans

class Solution {
    public int maxRotateFunction(int[] nums) {
        long f = 0;
        long s = 0;
        int n = nums.length;
        for (int i = 0; i < n; ++i) {
            f += 1L * i * nums[i];
            s += nums[i];
        }
        long ans = f;
        for (int i = 1; i < n; ++i) {
            f = f + s - 1L * n * nums[n - i];
            ans = Math.max(ans, f);
        }
        return (int) ans;
    }
}

