function maxRotateFunction(nums: number[]): number {
    const n = nums.length;
    const sum = nums.reduce((r, v) => r + v);
    let res = nums.reduce((r, v, i) => r + v * i, 0);
    let pre = res;
    for (let i = 1; i < n; i++) {
        pre = pre - (sum - nums[i - 1]) + nums[i - 1] * (n - 1);
        res = Math.max(res, pre);
    }
    return res;
}

impl Solution {
    pub fn max_rotate_function(nums: Vec<i32>) -> i32 {
        let n = nums.len();
        let sum: i64 = nums.iter().map(|&v| v as i64).sum();
        let mut pre: i64 = nums
            .iter()
            .enumerate()
            .map(|(i, &v)| i as i64 * v as i64)
            .sum();
        (0..n)
            .map(|i| {
                let res = pre;
                pre = pre - (sum - nums[i] as i64) + nums[i] as i64 * (n as i64 - 1);
                res
            })
            .max()
            .unwrap_or(0) as i32
    }
}

